Here is the commit message:
wifi: mt76: mt7925: prevent NULL pointer dereference in
 mt7925_tx_check_aggr()

Move the NULL check for 'sta' before dereferencing it to prevent a
possible crash.

Fixes: 44eb173bdd4f ("wifi: mt76: mt7925: add link handling in mt7925_txwi_free")
Signed-off-by: Ming Yen Hsieh <mingyen.hsieh@mediatek.com>
Link: https://patch.msgid.link/20250904030649.655436-4-mingyen.hsieh@mediatek.com
Signed-off-by: Felix Fietkau <nbd@nbd.name>

Here is the root cause:
The function `mt7925_tx_check_aggr()` dereferences the `sta` pointer (via `rcu_dereference(sta->link[wcid->link_id])`) before performing a NULL check on `sta`. The original code had a `if (!sta || ...)` check after the dereference, which allowed a NULL pointer crash if `sta` is NULL because the dereference occurs first.

Here is the patch:

 static void mt7925_tx_check_aggr(struct ieee80211_sta *sta, struct sk_buff *skb,
 				 struct mt76_wcid *wcid)
 {
 	struct ieee80211_tx_info *info = IEEE80211_SKB_CB(skb);
 	struct ieee80211_link_sta *link_sta;
 	struct mt792x_link_sta *mlink;
 	struct mt792x_sta *msta;
 	bool is_8023;
 	u16 fc, tid;

+	if (!sta)
+		return;
+
 	link_sta = rcu_dereference(sta->link[wcid->link_id]);
 	if (!link_sta)
 		return;

-	if (!sta || !(link_sta->ht_cap.ht_supported || link_sta->he_cap.has_he))
+	if (!(link_sta->ht_cap.ht_supported || link_sta->he_cap.has_he))
 		return;

 	tid = skb->priority & IEEE80211_QOS_CTL_TID_MASK;
 	is_8023 = info->flags & IEEE80211_TX_CTL_HW_80211_ENCAP;

 	if (is_8023) {
 		fc = IEEE80211_FTYPE_DATA |
 		     (sta->wme ? IEEE80211_STYPE_QOS_DATA :
 		      IEEE80211_STYPE_DATA);
 	} else {
 		/* No need to get precise TID for Action/Management Frame,
 		 * since it will not meet the following Frame Control
 		 * condition anyway.
 		 */

 		struct ieee80211_hdr *hdr = (struct ieee80211_hdr *)skb->data;

 		fc = le16_to_cpu(hdr->frame_control) &
 		     (IEEE80211_FCTL_FTYPE | IEEE80211_FCTL_STYPE);
 	}

 	if (unlikely(fc != (IEEE80211_FTYPE_DATA | IEEE80211_STYPE_QOS_DATA)))
 		return;

 	msta = (struct mt792x_sta *)sta->drv_priv;

 	if (sta->mlo && msta->deflink_id != IEEE80211_LINK_UNSPECIFIED)
 		mlink = rcu_dereference(msta->link[msta->deflink_id]);
 	else
 		mlink = &msta->deflink;

 	if (!test_and_set_bit(tid, &mlink->wcid.ampdu_state)) {
 		if (ieee80211_start_tx_ba_session(sta, tid, 0))
 			clear_bit(tid, &mlink->wcid.ampdu_state);
 	}
 }



